const isSearchPage=window.location.pathname.replace(/\/$/,"").endsWith("/search");function triggerSearch(e){const t=e.trim();if(!t)return;if(isSearchPage)executeSearch(t);else{const e=new URL("/search/",window.location.origin);e.searchParams.set("q",t),window.location.href=e.toString()}}document.querySelectorAll(".search-box-form").forEach(e=>{e.addEventListener("submit",function(e){const t=this.querySelector('input[name="q"]'),n=t?t.value:"";isSearchPage&&(e.preventDefault(),triggerSearch(n))})}),document.querySelectorAll(".siteSearchButton").forEach(e=>{e.addEventListener("click",function(e){const t=this.closest("form"),n=t?t.querySelector('input[name="q"]'):null;n&&(e.preventDefault(),triggerSearch(n.value))})})